Lemma cb_splitA : forall m A (n k : nat) j, (k <= n)%nat -> rw_cells asegs m A [CB n j] ->
  (exists j1, rw_cells asegs m A [CB k j1]) /\ (exists j2, rw_cells asegs m (A + Z.of_nat k) [CB (n - k) j2]).
