Definition x2win (SPA DT mtl W : Z) (iv : Z * Z) : Prop :=
  fst iv <= snd iv /\
  ((SPA + 16 <= fst iv /\ snd iv <= SPA + 112) \/ (SPA + 128 <= fst iv /\ snd iv <= SPA + 720)
   \/ (DT <= fst iv /\ snd iv <= DT + DTABLE_BYTES mtl) \/ (W <= fst iv /\ snd iv <= W + 8704)).

